CREATE TABLE ExternalRating(ExternalRatingID INTEGER PRIMARY KEY, GameID INTEGER NOT NULL, GameEditionID INTEGER, RatingSourceID INTEGER NOT NULL, RatingTypeID INTEGER NOT NULL, RatingValue DECIMAL(4,2) NOT NULL, RawRatingValue DECIMAL(8,2), ObservationDate DATE, FOREIGN KEY (GameID) REFERENCES Game(GameID), FOREIGN KEY (GameEditionID) REFERENCES GameEdition(GameEditionID), FOREIGN KEY (RatingSourceID) REFERENCES RatingSource(RatingSourceID), FOREIGN KEY (RatingTypeID) REFERENCES RatingType(RatingTypeID), CHECK((RatingValue BETWEEN 0 AND 10)), CHECK((RawRatingValue >= 0)));
